const it = $input.first();
const m = it.json;
const h = {};
if (m.headers && typeof m.headers === 'object' && !Array.isArray(m.headers)) {
  for (const [k, v] of Object.entries(m.headers)) h[k.toLowerCase()] = typeof v === 'string' ? v : (v && v.text) || JSON.stringify(v);
}
if (Array.isArray(m.payload?.headers)) for (const x of m.payload.headers) h[String(x.name).toLowerCase()] = x.value;
const gmail_id = m.id || $('Un correo a la vez').first().json.id;
const fromV = m.from?.value?.[0] || {};
const fromTxt = String(m.from?.text || (typeof m.from === 'string' ? m.from : '') || '');
const de_correo = String(fromV.address || (fromTxt.match(/<([^>]+)>/) || [])[1] || fromTxt).trim().toLowerCase();
const de_nombre = (fromV.name || '').trim() || null;
const asunto = String(m.subject || '(sin asunto)').replace(/\s+/g, ' ').trim();
let cuerpo = String(m.text || '').trim();
if (!cuerpo && m.html) {
  cuerpo = String(m.html)
    .replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|tr|li)>/gi, '\n').replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
    .replace(/\n{3,}/g, '\n\n').trim();
}
const message_id = String(m.messageId || h['message-id'] || `<gmail-${gmail_id}@sin-message-id>`).trim();
const in_reply_to = String(m.inReplyTo || h['in-reply-to'] || '').trim() || null;
const refsRaw = m.references || h['references'] || '';
const references = (Array.isArray(refsRaw) ? refsRaw : String(refsRaw).split(/\s+/)).filter(Boolean);
const fecha = new Date(m.date || Date.now());
const recibido_en = (isNaN(fecha) ? new Date() : fecha).toISOString();
const ids_citados = [...new Set([in_reply_to, ...references].filter(Boolean))];
const tiene_etiqueta = /\[SGD\s/i.test(asunto);
const attachmentKeys = Object.keys(it.binary || {}).filter(k => k.startsWith('attachment_'));
return [{ json: { gmail_id, message_id, in_reply_to, references, ids_citados, de_nombre, de_correo, asunto, cuerpo: cuerpo.slice(0, 15000), recibido_en, tiene_etiqueta, tiene_adjuntos: attachmentKeys.length > 0, adjuntos_binarios: attachmentKeys } }];

const n = $('Normalizar correo').first().json;
const q = $('Consultar estado').first().json;
const dep = $('Buscar dependencia').first().json;
const coms = $('Buscar comunicaciones').first().json || [];
const ctx = {
  de: `${n.de_nombre || ''} <${n.de_correo}>`,
  asunto: n.asunto,
  cuerpo: n.cuerpo,
  message_id: n.message_id,
  in_reply_to: n.in_reply_to,
  references: n.references.join(', ') || 'ninguno',
  tiene_etiqueta_sgd: n.tiene_etiqueta ? 'SÍ' : 'NO',
  existe_message_id: q.ya_procesado ? 'SÍ (ya fue procesado)' : 'NO',
  comunicacion_previa_id: q.comunicacion_id || 'ninguna',
  dependencia_previa_id: q.dependencia_id || 'ninguna',
  remitente_es_dependencia: dep.id ? `SÍ - ${dep.nombre}` : 'NO',
  comunicaciones_recientes: coms.length ? coms.map(c => `- ${c.consecutivo}: ${c.asunto} (${c.estado})`).join('\n') : 'ninguna'
};
return [{ json: ctx }];

const n = $('Normalizar correo').first().json;
const q = $('Consultar estado').first().json;
const dep = $('Buscar dependencia').first().json;
const crudo = String($input.first().json.output || '').replace(/```json|```/g, '').trim();
let tipo = 'correo_nuevo';
let comunicacion_id = q.comunicacion_id || null;
let dependencia_id = q.dependencia_id || dep.id || null;
let motivo = 'Clasificación por agente';
try {
  const j = JSON.parse(crudo.slice(crudo.indexOf('{'), crudo.lastIndexOf('}') + 1));
  tipo = j.tipo || tipo;
  comunicacion_id = j.comunicacion_id ?? comunicacion_id;
  dependencia_id = j.dependencia_id ?? dependencia_id;
  motivo = j.motivo || motivo;
} catch (e) {
  if (q.ya_procesado || q.es_propio) tipo = 'spam';
  else if (q.comunicacion_id && q.dependencia_id) tipo = 'respuesta_dependencia';
  else if (q.comunicacion_id) tipo = 'sin_asociar';
  else if (/delivery failure|undeliverable|bounce|no such user/i.test(n.asunto + ' ' + n.cuerpo)) tipo = 'rebote';
  else if (/unsubscribe|newsletter|promoción|oferta|publicidad/i.test(n.asunto + ' ' + n.cuerpo)) tipo = 'spam';
  motivo = 'Fallback por error en respuesta del agente';
}
return [{ json: { ...n, tipo, comunicacion_id, dependencia_id, motivo } }];
